CREATE TABLE IF NOT EXISTS bank_accounts (id BIGINT PRIMARY KEY AUTO_INCREMENT, account_number VARCHAR(20) NOT NULL UNIQUE, full_name VARCHAR(100) NOT NULL, email VARCHAR(150) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, balance DECIMAL(15,2) NOT NULL DEFAULT 0.00, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS bank_transactions (id BIGINT PRIMARY KEY AUTO_INCREMENT, account_id BIGINT NOT NULL, transaction_type VARCHAR(20) NOT NULL, amount DECIMAL(15,2) NOT NULL, description VARCHAR(255) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_transaction_account FOREIGN KEY (account_id) REFERENCES bank_accounts(id));
CREATE INDEX idx_transactions_account_date ON bank_transactions(account_id, created_at);
